(function() {
    'use strict';

    class SigmaShiftAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'SigmaShift — Six Sigma & Quality Management';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    phase: 'Define & Measure',
                    phaseKey: 'phase_define_measure',
                    controlsId: 'round1Controls',
                    description: '<b>DMAIC Phase: DEFINE & MEASURE</b><br><br>You are the newly assigned Lean Six Sigma Black Belt team at <b>Cervecería del Pacífico</b>, a regional brewery in Medellín, Colombia. The canning line (Line 3) has a <b>7.8% defect rate</b> — nearly four times the industry benchmark of 2.1%.<br><br><b>Defect breakdown (from initial data):</b><br>• Under-fill / Over-fill: 34%<br>• Seal failure: 28%<br>• Label misalignment: 19%<br>• Contamination: 12%<br>• Other: 7%<br><br>The plant manager has approved a <b>$180,000 budget</b> for a 12-week DMAIC project. Your first task: define the project scope, select CTQ characteristics, invest in a measurement system, and choose your sample size to establish a reliable baseline.'
                },
                {
                    phase: 'Analyze',
                    phaseKey: 'phase_analyze',
                    controlsId: 'round2Controls',
                    description: '<b>DMAIC Phase: ANALYZE</b><br><br>Your measurement system is in place and the baseline has been established. Now you must analyze the data to find the root causes of the high defect rate.<br><br><b>Control chart signals detected:</b><br>• X-bar chart shows a gradual upward drift in fill volume variation over the last 4 weeks<br>• R chart shows increasing range on the morning shift<br>• Two points beyond the upper control limit coincide with temperature sensor readings above 8°C from target<br><br><b>Pareto analysis confirms:</b> Fill-related defects (34%) and seal failures (28%) account for 62% of all defects.<br><br>Select your analytical approach, allocate budget to analysis tools, and identify your top two root cause hypotheses. The accuracy of your diagnosis will determine how effective your improvements will be.'
                },
                {
                    phase: 'Improve',
                    phaseKey: 'phase_improve',
                    controlsId: 'round3Controls',
                    description: '<b>DMAIC Phase: IMPROVE</b><br><br>Your analysis is complete. Now allocate your remaining budget across improvement interventions.<br><br><b>Available interventions:</b><br>• <b>Temperature Calibration System</b> — Automated recalibration of filling head temperature sensors. Directly addresses fill volume drift. Cost: $15K–$60K depending on scope.<br>• <b>Gasket Replacement Program</b> — Systematic replacement of worn sealing gaskets. Addresses seal pressure inconsistency. Cost: $10K–$35K.<br>• <b>Label System Realignment</b> — Mechanical realignment of label applicator. Addresses misalignment defects. Cost: $8K–$25K.<br>• <b>Contamination Controls</b> — Enhanced filtration and raw material testing. Addresses contamination. Cost: $10K–$25K.<br>• <b>Operator Training</b> — SPC awareness and standard work procedures. General improvement. Cost: $5K–$20K.<br><br>Invest wisely. Spending on the wrong root cause wastes budget without reducing defects.'
                },
                {
                    phase: 'Control',
                    phaseKey: 'phase_control',
                    controlsId: 'round4Controls',
                    description: '<b>DMAIC Phase: CONTROL</b><br><br>Your improvement interventions have been implemented. The defect rate has shifted based on how accurately you targeted the root causes.<br><br>Now you must design a control system to <b>sustain the gains</b>. Without proper controls, processes tend to drift back to their previous state within 6–12 months.<br><br>Design your control plan by selecting:<br>• SPC implementation level (how process data is monitored)<br>• Process audit frequency (how often the system is reviewed)<br>• Operator training program (workforce capability)<br>• Escalation protocol (how out-of-control signals are handled)<br><br>A strong control plan protects your improvements. A weak one means the project was a temporary fix.'
                }
            ];

            this.ROOT_CAUSE_WEIGHTS = {
                temp_drift: 0.61,
                seal_pressure: 0.22,
                label_alignment: 0.10,
                contamination: 0.05,
                operator_error: 0.015,
                maintenance: 0.005
            };

            this.EVENTS = [
                { round: 2, probability: 0.7, key: 'gauge_error', message: '<b>⚠️ Measurement System Alert:</b> The lab has discovered a 15% Gauge R&R error in the fill volume measurement system. Your baseline data may overstate the true process variation. Consider this when interpreting control chart signals.' },
                { round: 3, probability: 0.5, key: 'recent_maintenance', message: '<b>🛠️ Maintenance Update:</b> The maintenance team reports that Filling Head #3 was recalibrated last week. However, the calibration drift pattern suggests a systemic issue across all filling heads, not just a single unit.' },
                { round: 3, probability: 0.4, key: 'audit_pressure', message: '<b>📢 Management Pressure:</b> The plant manager is asking whether the project can be closed early to show quick results before the quarterly board meeting. Defending the value of the Control phase is critical.' },
                { round: 4, probability: 0.5, key: 'new_supplier', message: '<b>📦 Supply Change:</b> A new can supplier has shipped a batch with slightly different dimensional tolerances. Your control plan must be robust enough to detect and respond to this new source of variation.' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 180000,
                    budgetSpent: 0,
                    defectRate: 0.078,
                    processSigma: 2.72,
                    baselineSigma: 0,
                    measurementAccuracy: 0,
                    rootCauseScore: 0,
                    analysisComplete: false,
                    controlPlanScore: 0,
                    sigmaScore: 0,
                    tamperedFlag: false,
                    activeEvents: [],
                    sigmaHistory: [],
                    defectRateHistory: [],
                    budgetHistory: [],
                    scoreHistory: [],
                    roundSpending: [],
                    checkpoints: {},
                    eventRolls: {},
                    r3Noise: null
                };
            }
            var __ds = state.domainState;
            if (!__ds.checkpoints) __ds.checkpoints = {};
            if (!__ds.eventRolls) __ds.eventRolls = {};
            if (__ds.r3Noise === undefined) __ds.r3Noise = null;
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    scopeSelect: 'canning_only',
                    ctqSelect: 'all_ctqs',
                    measurementBudget: 15000,
                    sampleSizeSelect: 'medium'
                };
            }
            this._updateBriefing(state);
        }

        // Idempotency helpers (mirror sim 134): snapshot pre-round mutable state so a
        // recompute of the same period restores it, preventing compounding on
        // double-submit / undo+resubmit. History arrays are truncated to round-1.
        _snapshot(ds) {
            return {
                budget: ds.budget, budgetSpent: ds.budgetSpent,
                defectRate: ds.defectRate, processSigma: ds.processSigma,
                baselineSigma: ds.baselineSigma, measurementAccuracy: ds.measurementAccuracy,
                rootCauseScore: ds.rootCauseScore, analysisComplete: ds.analysisComplete,
                analysisQuality: ds.analysisQuality, controlPlanScore: ds.controlPlanScore,
                sigmaScore: ds.sigmaScore, tamperedFlag: ds.tamperedFlag,
                activeEvents: (ds.activeEvents || []).slice()
            };
        }
        _restore(ds, s, round) {
            ds.budget = s.budget; ds.budgetSpent = s.budgetSpent;
            ds.defectRate = s.defectRate; ds.processSigma = s.processSigma;
            ds.baselineSigma = s.baselineSigma; ds.measurementAccuracy = s.measurementAccuracy;
            ds.rootCauseScore = s.rootCauseScore; ds.analysisComplete = s.analysisComplete;
            ds.analysisQuality = s.analysisQuality; ds.controlPlanScore = s.controlPlanScore;
            ds.sigmaScore = s.sigmaScore; ds.tamperedFlag = s.tamperedFlag;
            ds.activeEvents = (s.activeEvents || []).slice();
            ds.sigmaHistory.length = round - 1;
            ds.defectRateHistory.length = round - 1;
            ds.budgetHistory.length = round - 1;
            ds.scoreHistory.length = round - 1;
            ds.roundSpending.length = round - 1;
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.description;

            var phaseEl = document.getElementById('phaseDisplay');
            if (phaseEl) {
                phaseEl.textContent = round.phase;
                phaseEl.setAttribute('data-i18n', round.phaseKey);
            }

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var ctrl = document.getElementById(this.ROUNDS[i].controlsId);
                if (ctrl) ctrl.style.display = (i === idx) ? 'block' : 'none';
            }

            if (idx === 2 && state.domainState) {
                var remEl = document.getElementById('remainingBudgetDisplay');
                if (remEl) {
                    remEl.textContent = 'Remaining Budget: $' + state.domainState.budget.toLocaleString();
                }
            }

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText) {
                var roundEvents = this.EVENTS.filter(function(e) { return e.round === (idx + 1); });
                var triggered = [];
                for (var j = 0; j < roundEvents.length; j++) {
                    if (state.domainState && state.domainState.activeEvents && state.domainState.activeEvents.indexOf(roundEvents[j].key) >= 0) {
                        triggered.push(roundEvents[j].message);
                    }
                }
                if (triggered.length > 0) {
                    eventText.innerHTML = triggered.join('<br><br>');
                    eventPanel.style.display = 'block';
                } else {
                    eventPanel.style.display = 'none';
                }
            }
        }

        _triggerEvents(state) {
            var currentRound = state.currentPeriod || 1;
            var roundEvents = this.EVENTS.filter(function(e) { return e.round === currentRound; });
            var ds = state.domainState;
            if (!ds.eventRolls) ds.eventRolls = {};
            for (var i = 0; i < roundEvents.length; i++) {
                var __k = roundEvents[i].key;
                if (ds.eventRolls[__k] === undefined) {
                    ds.eventRolls[__k] = (Math.random() < roundEvents[i].probability);
                }
                if (ds.eventRolls[__k] && ds.activeEvents.indexOf(__k) < 0) {
                    ds.activeEvents.push(__k);
                }
            }
        }

        _defectRateToSigma(defectRate) {
            if (defectRate <= 0.0001) return 5.2;
            if (defectRate <= 0.001) return 4.6;
            if (defectRate <= 0.005) return 4.1;
            if (defectRate <= 0.01) return 3.8;
            if (defectRate <= 0.02) return 3.55;
            if (defectRate <= 0.03) return 3.38;
            if (defectRate <= 0.04) return 3.25;
            if (defectRate <= 0.05) return 3.14;
            if (defectRate <= 0.06) return 3.05;
            if (defectRate <= 0.07) return 2.8;
            if (defectRate <= 0.08) return 2.72;
            if (defectRate <= 0.10) return 2.6;
            if (defectRate <= 0.15) return 2.35;
            return 2.0;
        }

        validateDecisions(decisions) {
            var currentRound = window.mySimulation.state.currentPeriod || 1;
            this._updateBriefing(window.mySimulation.state);

            if (currentRound === 1) {
                var scopeEl = document.getElementById('scopeSelect');
                if (scopeEl) decisions.scopeSelect = scopeEl.value;
                var ctqEl = document.getElementById('ctqSelect');
                if (ctqEl) decisions.ctqSelect = ctqEl.value;
                var measEl = document.getElementById('measurementBudget');
                if (measEl) decisions.measurementBudget = parseInt(measEl.value);
                var sampEl = document.getElementById('sampleSizeSelect');
                if (sampEl) decisions.sampleSizeSelect = sampEl.value;

                if (!decisions.measurementBudget || decisions.measurementBudget < 5000 || decisions.measurementBudget > 30000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('measurement_budget_warning'), 'warning');
                    return false;
                }
            } else if (currentRound === 2) {
                var anaEl = document.getElementById('analysisBudget');
                if (anaEl) decisions.analysisBudget = parseInt(anaEl.value);
                var toolEl = document.getElementById('toolFocus');
                if (toolEl) decisions.toolFocus = toolEl.value;
                var rc1El = document.getElementById('rootCause1');
                if (rc1El) decisions.rootCause1 = rc1El.value;
                var rc2El = document.getElementById('rootCause2');
                if (rc2El) decisions.rootCause2 = rc2El.value;

                if (!decisions.analysisBudget || decisions.analysisBudget < 5000 || decisions.analysisBudget > 40000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('analysis_budget_warning'), 'warning');
                    return false;
                }
                var totalSpentSoFar = window.mySimulation.state.domainState.budgetSpent + decisions.analysisBudget;
                if (totalSpentSoFar > 180000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('over_budget_warning'), 'warning');
                    return false;
                }
            } else if (currentRound === 3) {
                var tcEl = document.getElementById('tempCalBudget');
                if (tcEl) decisions.tempCalBudget = parseInt(tcEl.value) || 0;
                var gkEl = document.getElementById('gasketBudget');
                if (gkEl) decisions.gasketBudget = parseInt(gkEl.value) || 0;
                var lbEl = document.getElementById('labelBudget');
                if (lbEl) decisions.labelBudget = parseInt(lbEl.value) || 0;
                var ctEl = document.getElementById('contaminationBudget');
                if (ctEl) decisions.contaminationBudget = parseInt(ctEl.value) || 0;
                var otEl = document.getElementById('opTrainingBudget');
                if (otEl) decisions.opTrainingBudget = parseInt(otEl.value) || 0;

                var roundTotal = decisions.tempCalBudget + decisions.gasketBudget + decisions.labelBudget + decisions.contaminationBudget + decisions.opTrainingBudget;
                var remaining = window.mySimulation.state.domainState.budget;
                if (roundTotal > remaining) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('over_budget_warning'), 'warning');
                    return false;
                }
                if (roundTotal === 0) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('no_investment_warning'), 'warning');
                    return false;
                }
            } else if (currentRound === 4) {
                var spcEl = document.getElementById('spcLevel');
                if (spcEl) decisions.spcLevel = spcEl.value;
                var auditEl = document.getElementById('auditFreq');
                if (auditEl) decisions.auditFreq = auditEl.value;
                var trainEl = document.getElementById('trainingLevel');
                if (trainEl) decisions.trainingLevel = trainEl.value;
                var escEl = document.getElementById('escalationProtocol');
                if (escEl) decisions.escalationProtocol = escEl.value;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var currentRound = state.currentPeriod;
            var roundSpend = 0;
            var results = { period: currentRound };

            // Idempotency guard: restore pre-round snapshot on recompute so
            // double-submit / undo+resubmit never compounds defect reduction,
            // budget spend, or history pushes. Random rolls persist (eventRolls/r3Noise).
            if (!ds.checkpoints) ds.checkpoints = {};
            if (ds.checkpoints[currentRound]) {
                this._restore(ds, ds.checkpoints[currentRound], currentRound);
            } else {
                ds.checkpoints[currentRound] = this._snapshot(ds);
            }

            this._triggerEvents(state);

            if (currentRound === 1) {
                roundSpend = d.measurementBudget;
                var scopeBonus = d.scopeSelect === 'canning_only' ? 1.0 : (d.scopeSelect === 'full_line' ? 0.6 : 0.5);
                var ctqBonus = d.ctqSelect === 'all_ctqs' ? 1.0 : 0.7;
                var sampleBonus = d.sampleSizeSelect === 'large' ? 1.0 : (d.sampleSizeSelect === 'medium' ? 0.8 : 0.5);
                var investmentBonus = Math.min(d.measurementBudget / 25000, 1.0);
                ds.measurementAccuracy = Math.round((scopeBonus * 0.25 + ctqBonus * 0.25 + sampleBonus * 0.25 + investmentBonus * 0.25) * 100);
                ds.baselineSigma = ds.processSigma;
                results.measurementAccuracy = ds.measurementAccuracy;
                results.baselineSigma = ds.baselineSigma;
                results.baselineDefectRate = ds.defectRate;
                results.roundSpend = roundSpend;
                results.phase = 'Define & Measure';

            } else if (currentRound === 2) {
                roundSpend = d.analysisBudget;
                var toolBonus = d.toolFocus === 'balanced' ? 1.0 : 0.65;
                var investBonus2 = Math.min(d.analysisBudget / 30000, 1.0);
                var rc1Weight = this.ROOT_CAUSE_WEIGHTS[d.rootCause1] || 0;
                var rc2Weight = this.ROOT_CAUSE_WEIGHTS[d.rootCause2] || 0;
                var rcScore = Math.round(((rc1Weight * 0.65 + rc2Weight * 0.35) / 0.61) * 100);
                rcScore = Math.min(rcScore, 100);
                var analysisQuality = toolBonus * 0.3 + investBonus2 * 0.2 + (rcScore / 100) * 0.5;
                ds.rootCauseScore = rcScore;
                ds.analysisComplete = true;
                ds.analysisQuality = Math.round(analysisQuality * 100);
                results.rootCauseScore = rcScore;
                results.analysisQuality = ds.analysisQuality;
                results.primaryHypothesis = d.rootCause1;
                results.secondaryHypothesis = d.rootCause2;
                results.roundSpend = roundSpend;
                results.phase = 'Analyze';

            } else if (currentRound === 3) {
                var tempSpend = d.tempCalBudget || 0;
                var gasketSpend = d.gasketBudget || 0;
                var labelSpend = d.labelBudget || 0;
                var contamSpend = d.contaminationBudget || 0;
                var trainSpend = d.opTrainingBudget || 0;
                roundSpend = tempSpend + gasketSpend + labelSpend + contamSpend + trainSpend;

                var tempEffect = Math.min(tempSpend / 45000, 1.0) * 0.61;
                var gasketEffect = Math.min(gasketSpend / 30000, 1.0) * 0.22;
                var labelEffect = Math.min(labelSpend / 20000, 1.0) * 0.10;
                var contamEffect = Math.min(contamSpend / 20000, 1.0) * 0.05;
                var trainEffect = Math.min(trainSpend / 15000, 1.0) * 0.02;
                var totalReduction = tempEffect + gasketEffect + labelEffect + contamEffect + trainEffect;

                var analysisMultiplier = ds.analysisComplete ? (0.7 + (ds.analysisQuality / 100) * 0.3) : 0.4;
                totalReduction = totalReduction * analysisMultiplier;

                var newDefectRate = ds.defectRate * (1 - totalReduction);
                newDefectRate = Math.max(newDefectRate, 0.005);
                if (ds.r3Noise === undefined || ds.r3Noise === null) {
                    ds.r3Noise = (Math.random() - 0.5) * 0.003;
                }
                newDefectRate = Math.max(newDefectRate + ds.r3Noise, 0.003);

                ds.defectRate = Math.round(newDefectRate * 10000) / 10000;
                ds.processSigma = this._defectRateToSigma(ds.defectRate);

                if (!ds.analysisComplete) {
                    ds.tamperedFlag = true;
                }

                results.defectReduction = Math.round(totalReduction * 100);
                results.newDefectRate = ds.defectRate;
                results.newSigma = ds.processSigma;
                results.roundSpend = roundSpend;
                results.phase = 'Improve';

            } else if (currentRound === 4) {
                roundSpend = 0;
                var spcScore = d.spcLevel === 'realtime' ? 30 : (d.spcLevel === 'advanced' ? 22 : 12);
                var auditScore = d.auditFreq === 'weekly' ? 25 : (d.auditFreq === 'biweekly' ? 18 : 10);
                var trainScore = d.trainingLevel === 'comprehensive' ? 25 : (d.trainingLevel === 'basic' ? 15 : 0);
                var escScore = d.escalationProtocol === 'formal' ? 20 : (d.escalationProtocol === 'informal' ? 10 : 0);
                ds.controlPlanScore = Math.min(spcScore + auditScore + trainScore + escScore, 100);

                var sigmaAchievement = Math.min(((ds.processSigma - ds.baselineSigma) / (4.1 - ds.baselineSigma)) * 35, 35);
                var rcAccuracy = (ds.rootCauseScore / 100) * 30;
                var budgetEff = Math.max(0, (1 - ds.budgetSpent / 180000) * 0.5 + 0.5) * 20;
                var controlComp = (ds.controlPlanScore / 100) * 15;

                var penalties = 0;
                if (ds.baselineSigma === 0) penalties += 20;
                if (ds.tamperedFlag) penalties += 15;
                if (ds.rootCauseScore < 30) penalties += 25;

                ds.sigmaScore = Math.max(0, Math.round(sigmaAchievement + rcAccuracy + budgetEff + controlComp - penalties));
                ds.sigmaScore = Math.min(ds.sigmaScore, 100);

                results.controlPlanScore = ds.controlPlanScore;
                results.finalSigma = ds.processSigma;
                results.finalDefectRate = ds.defectRate;
                results.sigmaScore = ds.sigmaScore;
                results.roundSpend = roundSpend;
                results.phase = 'Control';
            }

            ds.budgetSpent += roundSpend;
            ds.budget = 180000 - ds.budgetSpent;
            ds.sigmaHistory.push(ds.processSigma);
            ds.defectRateHistory.push(Math.round(ds.defectRate * 10000) / 100);
            ds.budgetHistory.push(ds.budget);
            ds.scoreHistory.push(ds.sigmaScore);
            ds.roundSpending.push(roundSpend);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            return results;
        }

