        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastEntry = history[history.length - 1];
            var finalSigma = lastEntry.results ? lastEntry.results.finalSigma || 0 : 0;
            var finalScore = lastEntry.results ? lastEntry.results.sigmaScore || 0 : 0;
            var finalDefect = lastEntry.results ? lastEntry.results.finalDefectRate || 0 : 0;

            var performance = 'Needs Improvement';
            if (finalScore >= 80) performance = 'Excellent — Master Black Belt Material';
            else if (finalScore >= 60) performance = 'Good — Solid DMAIC Execution';
            else if (finalScore >= 40) performance = 'Developing — Review Analytical Rigor';

            var insights = [];
            if (finalSigma >= 3.8) {
                insights.push('Outstanding sigma improvement. The process is now approaching world-class levels.');
            } else if (finalSigma >= 3.2) {
                insights.push('Meaningful improvement achieved. Further gains require addressing remaining root causes.');
            } else {
                insights.push('Limited improvement suggests the dominant root cause was not fully addressed. Review root cause analysis methodology.');
            }

            var r2 = history[1];
            if (r2 && r2.results && r2.results.rootCauseScore >= 80) {
                insights.push('Strong root cause identification. Data-driven analysis led to effective targeting.');
            } else if (r2 && r2.results && r2.results.rootCauseScore < 40) {
                insights.push('Root cause diagnosis missed the dominant factor (temperature calibration drift). In real DMAIC projects, this would result in wasted improvement budget.');
            }

            return {
                finalSigma: finalSigma,
                finalDefectRate: finalDefect,
                sigmaScore: finalScore,
                performance: performance,
                insights: insights
            };
        }

